        "uz": "Toshkent davlat iqtisodiyot universiteti Raqamli iqtisodiyot va axborot texnologiyalari fakulteti Sun’iy intellekt kafedrasi katta o‘qituvchisi. 2014-yilda Muhammad al-Xorazmiy nomidagi Toshkent axborot texnologiyalari universitetining bakalavriat bosqichini tamomlagan. 2015-yilda Sergeli politexnika kasb-hunar kollejida o‘qituvchi bo‘lib ishlagan. 2016-yilda Simplex Service Group kompaniyasida dasturchi va kontent menejer sifatida faoliyat yuritgan. 2021-yilda Muhammad al-Xorazmiy nomidagi Toshkent axborot texnologiyalari universitetining magistratura bosqichini tamomlagan. 2021–2023-yillarda Mirzo Ulug‘bek nomidagi O‘zbekiston Milliy universitetining «Algoritmlash va dasturlash texnologiyalari» kafedrasida o‘qituvchi, 2023–2024-yillarda Toshkent axborot texnologiyalari universitetining «Informatika asoslari» kafedrasida o‘qituvchi bo‘lib ishlagan. 2024-yildan buyon Toshkent davlat iqtisodiyot universiteti Sun’iy intellekt kafedrasida katta o‘qituvchi lavozimida faoliyat yuritib kelmoqda. Raqamli platformalarning ijtimoiy xizmatlarda foydalanilish tajribasi",
